<?php use App\ViewModels\Developer\EntityCardViewModel; ?>
<article class="card entity-card ui-record ui-density-dense" data-ui-component="entity-card" data-ui-density="dense"><h3><?= htmlspecialchars($entityCard->entity["name"] ?? "") ?></h3><?php if (!empty($entityCard->entity["description"])): ?><p><?= htmlspecialchars($entityCard->entity["description"]) ?></p><?php endif; ?><dl class="detail-list ui-metadata-grid"><?php foreach ($entityCard->details as $label => $value): ?><div><dt><?= htmlspecialchars($label) ?></dt><dd><?= htmlspecialchars((string) $value) ?></dd></div><?php endforeach; ?></dl><?php if (!empty($entityCard->actions)): ?><div class="page-actions ui-action-group"><?php foreach ($entityCard->actions as $action): ?><?php if (($action["method"] ?? "GET") === "POST"): ?><form method="POST" action="<?= htmlspecialchars($action["href"]) ?>"><button type="submit"><?= htmlspecialchars($action["label"]) ?></button></form><?php else: ?><a href="<?= htmlspecialchars($action["href"]) ?>"><?= htmlspecialchars($action["label"]) ?></a><?php endif; ?><?php endforeach; ?></div><?php endif; ?></article>
